using NovaHarvest.Core.Crafting;using NovaHarvest.Core.Models;using NovaHarvest.Core.NPC;using NovaHarvest.Core.NPC.Characters;using NovaHarvest.Core.Player;using NovaHarvest.Core.Quests;using NovaHarvest.Core.World;namespace NovaHarvest.Core.Systems;public sealed class GameSession {public WorldManager World{get;}public PlayerController Player{get;}public PlayerInteraction PlayerInteraction{get;}public Inventory Inventory{get;}public ProgressionSystem Progression{get;}public NPCManager NPCs{get;}public ColonySystem Colony{get;}public QuestManager Quests{get;}public DialogueManager Dialogue{get;}public CraftingSystem Crafting{get;}public BuildingSystem Building{get;}public FarmingSystem Farming{get;}public InteractionSystem Interaction{get;}public WorldTime Time{get;}public EventSystem Events{get;}public GameSession(int startX=5,int startY=5,int? randomSeed=null){World=DemoWorld.Create();Player=new PlayerController(startX,startY);PlayerInteraction=new PlayerInteraction(Player);Inventory=new Inventory();Progression=new ProgressionSystem();NPCs=new NPCManager();Colony=new ColonySystem(NPCs);Quests=new QuestManager(NPCs,Progression);Dialogue=new DialogueManager();Crafting=new CraftingSystem(Inventory);Building=new BuildingSystem(Player,Inventory,World);Farming=new FarmingSystem(StarterSeeds.Create(),Inventory);Interaction=new InteractionSystem(Player,Inventory);Time=new WorldTime();Events=new EventSystem(randomSeed);RegisterStarterContent();Time.NewDay+=OnNewDay;}public void AdvanceTime(int minutes)=>Time.AdvanceMinutes(minutes);void RegisterStarterContent(){foreach(var r in StarterRecipes.Create())Crafting.AddRecipe(r);NPCs.Add(Lyra.Create());Quests.Add(LyraQuests.FirstQuest());Inventory.Add("seed_lumen_berry",5);Inventory.Add("alien_wood",10);Inventory.Add("stone",10);}void OnNewDay(){var plots=World.Objects.OfType<FarmPlotObject>().Select(x=>x.Plot).ToList();Farming.AdvanceDay(plots,Time.Day-1);}}
